package com.app.service;
import com.app.exception.ValidationException; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class SharedSplitCalculatorTest { @Test void distributesPaiseRemainder(){var r=SharedSplitCalculator.equal(new BigDecimal("100.00"),List.of(1L,2L,3L));assertEquals(new BigDecimal("33.34"),r.get(1L));assertEquals(new BigDecimal("33.33"),r.get(2L));assertEquals(new BigDecimal("100.00"),r.values().stream().reduce(BigDecimal.ZERO,BigDecimal::add));} @Test void rejectsInvalidParticipants(){assertThrows(ValidationException.class,()->SharedSplitCalculator.equal(new BigDecimal("10.00"),List.of()));assertThrows(ValidationException.class,()->SharedSplitCalculator.equal(new BigDecimal("10.00"),List.of(1L,1L)));} @Test void validatesExactTotal(){assertDoesNotThrow(()->SharedSplitCalculator.requireTotal(new BigDecimal("10.00"),List.of(new BigDecimal("4.00"),new BigDecimal("6.00"))));assertThrows(ValidationException.class,()->SharedSplitCalculator.requireTotal(new BigDecimal("10.00"),List.of(new BigDecimal("9.99"))));} }
